export function getKnowledgeNode(unitId) {
  return knowledgeNetwork[unitId] || {
    prerequisites: [],
    crossLinks: [],
    tags: ['觀念核心', '課綱必修'],
    senior: '銜接高中升學必備素養'
  };
}

export function renderKnowledgeMesh(u) {
  const node = getKnowledgeNode(u.id);
  const prereqUnits = (node.prerequisites || []).map(id => unitById[id]).filter(Boolean);
  const crossLinks = (node.crossLinks || []).map(c => ({
    ...c,
    targetUnit: unitById[c.unitId],
    targetSubject: unitById[c.unitId] ? subjectById[unitById[c.unitId].subject] : null
  })).filter(c => c.targetUnit && c.targetSubject);

  return `
    <section class="lesson-step knowledge-mesh-section" id="step-knowledge-mesh" aria-labelledby="mesh-title">
      <div class="step-label">KNOWLEDGE MESH / SYNAPSES & PREREQUISITES</div>
      <div class="mesh-header-row">
        <div class="mesh-title-wrap">
          <span class="mesh-icon">🌐</span>
          <div>
            <h2 id="mesh-title" style="margin:0 0 4px;font-size:1.25rem;">跨領域知識網絡與先備脈絡圖譜</h2>
            <p class="muted" style="margin:0;font-size:0.86rem;">拒絕碎片死記！看清概念在 108 課綱知識神經網絡中的位置與跨學科火花。</p>
          </div>
        </div>
      </div>

      <!-- Interactive SVG Concept Synapse Map -->
      <div class="concept-mesh-svg-card">
        <svg class="concept-svg" viewBox="0 0 680 180" width="100%" height="auto" role="img" aria-label="${u.title} 知識聯絡圖譜">
          <defs>
            <linearGradient id="centerGlow-${u.id}" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stop-color="#2d5c48"/>
              <stop offset="100%" stop-color="#193e35"/>
            </linearGradient>
            <linearGradient id="prereqGlow" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stop-color="#eaf3eb"/>
              <stop offset="100%" stop-color="#d3e7d8"/>
            </linearGradient>
            <linearGradient id="crossGlow" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stop-color="#fdf4e3"/>
              <stop offset="100%" stop-color="#faebd0"/>
            </linearGradient>
          </defs>
          <rect width="680" height="180" rx="12" fill="#fafbf9" stroke="#dfe6e1" stroke-width="1.2"/>
          
          <!-- Connectors -->
          <!-- Left Connector (Prerequisites) -->
          <line x1="160" y1="90" x2="340" y2="90" stroke="#8ba896" stroke-width="2" stroke-dasharray="4,4"/>
          <!-- Right Connectors (Cross Links) -->
          <line x1="340" y1="90" x2="520" y2="52" stroke="#d49b42" stroke-width="2"/>
          <line x1="340" y1="90" x2="520" y2="128" stroke="#3b789e" stroke-width="2"/>

          <!-- Left Node: Prerequisites -->
          <g transform="translate(60, 48)">
            <rect width="130" height="84" rx="8" fill="url(#prereqGlow)" stroke="#45825b" stroke-width="1.4"/>
            <text x="65" y="24" font-size="11" font-weight="700" fill="#2d5c48" text-anchor="middle">【先備概念基石】</text>
            <text x="65" y="46" font-size="9.5" fill="#1b362b" text-anchor="middle">${prereqUnits.length ? (prereqUnits[0].title.slice(0, 8) + '…') : '自學起點 / 直覺經驗'}</text>
            <text x="65" y="66" font-size="8.5" fill="#587467" text-anchor="middle">${prereqUnits.length > 1 ? ('及其他 ' + prereqUnits.length + ' 個基石') : '穩紮穩打不跳步'}</text>
          </g>

          <!-- Center Node: Current Unit -->
          <g transform="translate(260, 42)">
            <rect width="160" height="96" rx="10" fill="url(#centerGlow-${u.id})" stroke="#d6fa77" stroke-width="2.2" filter="drop-shadow(0 4px 10px rgba(25,62,53,0.25))"/>
            <text x="80" y="28" font-size="10.5" font-weight="800" fill="#d6fa77" text-anchor="middle">★ 本課核心單元</text>
            <text x="80" y="52" font-size="12" font-weight="800" fill="#ffffff" text-anchor="middle">${u.title.length > 9 ? (u.title.slice(0, 9) + '…') : u.title}</text>
            <rect x="25" y="66" width="110" height="18" rx="4" fill="#ffffff" opacity="0.15"/>
            <text x="80" y="79" font-size="9" fill="#e8f7ee" text-anchor="middle">${u.grade}年級 · ${subjectById[u.subject]?.name || ''}</text>
          </g>

          <!-- Right Top Node: Cross Domain 1 -->
          <g transform="translate(480, 20)">
            <rect width="150" height="64" rx="8" fill="url(#crossGlow)" stroke="#c4821a" stroke-width="1.4"/>
            <text x="75" y="22" font-size="10" font-weight="700" fill="#a06006" text-anchor="middle">⚡ 跨領域觸類旁通</text>
            <text x="75" y="42" font-size="9.5" fill="#2d3733" text-anchor="middle">${crossLinks[0]?.targetUnit?.title?.slice(0, 9) || '物理/幾何/生活應用'}…</text>
            <text x="75" y="55" font-size="8.5" fill="#755a30" text-anchor="middle">${crossLinks[0]?.badge || '跨科整合'}</text>
          </g>

          <!-- Right Bottom Node: Senior Horizon -->
          <g transform="translate(480, 96)">
            <rect width="150" height="64" rx="8" fill="#edf4fa" stroke="#3b789e" stroke-width="1.4"/>
            <text x="75" y="22" font-size="10" font-weight="700" fill="#2b5977" text-anchor="middle">🎓 高中學測遠眺</text>
            <text x="75" y="42" font-size="9" fill="#1e322d" text-anchor="middle">${node.senior.slice(0, 11)}…</text>
            <text x="75" y="55" font-size="8.5" fill="#4f6e62" text-anchor="middle">會考 × 學測連貫視野</text>
          </g>
        </svg>
      </div>

      <!-- Cards Grid -->
      <div class="mesh-cards-grid">
        <!-- Prerequisites Box -->
        <div class="mesh-card prereq-card">
          <div class="mesh-card-header">
            <span class="mesh-tag prereq">🔗 先備概念基石</span>
            <small class="muted">學本課前，建議先弄懂這些</small>
          </div>
          ${prereqUnits.length ? `
            <div class="prereq-list">
              ${prereqUnits.map(p => `
                <a class="prereq-item-link" href="#/lesson/${p.id}">
                  <span class="prereq-sub-badge">${subjectById[p.subject]?.name || ''}</span>
                  <strong>${p.title}</strong>
                  <span class="prereq-arrow">→</span>
                </a>
              `).join('')}
            </div>
          ` : `
            <div class="prereq-empty">
              <span>🌱 <strong>本單元為基礎起點</strong>，直接從生活經驗直覺進入即可，無需複雜先備運算！</span>
            </div>
          `}
        </div>

        <!-- Cross-Discipline Connections Box -->
        <div class="mesh-card cross-card">
          <div class="mesh-card-header">
            <span class="mesh-tag cross">⚡ 跨領域知識突觸</span>
            <small class="muted">跨學科連結，融會貫通</small>
          </div>
          ${crossLinks.length ? `
            <div class="cross-link-list">
              ${crossLinks.map(c => `
                <div class="cross-link-item">
                  <div class="cross-link-top">
                    <span class="cross-badge">${c.badge}</span>
                    <a class="cross-title-link" href="#/lesson/${c.targetUnit.id}">
                      ${c.targetSubject.name} · ${c.targetUnit.title} ↗
                    </a>
                  </div>
                  <p class="cross-reason">${c.reason}</p>
                </div>
              `).join('')}
            </div>
          ` : `
            <p class="subtle">本主題專注於該領域專屬思維與技法訓練。</p>
          `}
        </div>
      </div>

      <!-- Senior Horizon & Concept Tags Footer -->
      <div class="mesh-footer-box">
        <div class="mesh-senior-row">
          <span class="mesh-senior-badge">🎓 高中學測視野延伸</span>
          <p class="mesh-senior-desc">${node.senior}</p>
        </div>
        <div class="mesh-tags-row">
          <span class="subtle">💡 核心概念心智標籤：</span>
          <div class="mesh-tags-list">
            ${(node.tags || []).map(t => `<span class="mesh-concept-chip">#${t}</span>`).join('')}
          </div>
        </div>
      </div>
    </section>
  `;
}
